import React from 'react';
import { TrendingUp, TrendingDown, Loader2 } from 'lucide-react';
import type { WidgetProps, MappingConfig } from '../types';
import { useWidgetFetch } from '../hooks/useWidgetFetch';

/** Aplica la función de agregación sobre un array de valores numéricos */
function aggregate(values: number[], method: string): number {
  if (values.length === 0) return 0;
  switch (method) {
    case 'sum': return values.reduce((a, b) => a + b, 0);
    case 'average': return values.reduce((a, b) => a + b, 0) / values.length;
    case 'count': return values.length;
    case 'min': return Math.min(...values);
    case 'max': return Math.max(...values);
    case 'last': return values[values.length - 1];
    default: return values[0];
  }
}

const AGG_LABELS: Record<string, string> = {
  sum: 'Total', average: 'Promedio', count: 'Conteo', min: 'Mínimo', max: 'Máximo', last: 'Último',
};

const KpiVentasHoy: React.FC<WidgetProps> = ({ definition, period }) => {
  const { data: rawData, loading, error } = useWidgetFetch<Record<string, unknown> | Record<string, unknown>[]>(
    definition.widget_id,
    period,
    definition.refresh_policy,
    definition.field_mapping?.rename
  );

  if (loading) {
    return (
      <div className="w-full h-full flex items-center justify-center">
        <Loader2 className="w-6 h-6 text-blue-500 animate-spin" />
      </div>
    );
  }

  if (error || rawData == null) {
    throw new Error(error || 'Datos no disponibles para este KPI');
  }

  const cfg = definition.config_schema as (MappingConfig & { type: 'kpi' }) | undefined;
  const aggregation = cfg?.aggregation ?? 'last';

  const rows = Array.isArray(rawData) ? rawData : [rawData];

  // Extraer el valor numérico priorizando field_mapping.values[0] si está configurado
  const valueField = definition.field_mapping?.values?.[0] ?? 'value';
  const labelField = definition.field_mapping?.aliases?.[valueField] ?? valueField;

  // Convierte number o string-numérico a number (APIs Socrata devuelven todo como string)
  const toNum = (v: unknown): number | null => {
    if (typeof v === 'number') return v;
    if (typeof v === 'string' && v !== '.' && v.trim() !== '') {
      const n = parseFloat(v.replace(/,/g, ''));
      return isNaN(n) ? null : n;
    }
    return null;
  };

  const extractNumber = (row: Record<string, unknown>): number | null => {
    // 1. Campo configurado en field_mapping (acepta string o number)
    const n = toNum(row[valueField]);
    if (n !== null) return n;
    // 2. Fallback: primer campo numérico/string-numérico (excluye campos con "id")
    for (const [k, v] of Object.entries(row)) {
      if (!k.toLowerCase().includes('id')) {
        const fn = toNum(v);
        if (fn !== null) return fn;
      }
    }
    return null;
  };

  let valor: number;
  let etiqueta: string;

  if (rows.length <= 1) {
    // Un solo registro: mostrar directamente
    const row = rows[0] ?? {};
    valor = extractNumber(row) ?? 0;
    etiqueta = typeof row.label === 'string' ? row.label : labelField !== valueField ? labelField : definition.nombre;
  } else {
    // Múltiples registros: agregar valores
    const values = rows.map(extractNumber).filter((v): v is number => v !== null);
    valor = aggregate(values, aggregation);
    etiqueta = `${AGG_LABELS[aggregation] ?? aggregation} (${rows.length} registros)`;
  }

  const tendencia = (() => {
    if (rows.length !== 1) return 0;
    const row = rows[0] ?? {};
    const t = row.trend ?? row.tendencia;
    return typeof t === 'number' ? t : 0;
  })();

  const isPositive = tendencia >= 0;
  const prefix = cfg?.valuePrefix ?? '';
  const suffix = cfg?.valueSuffix ?? '';
  const formattedValue = `${prefix}${valor.toLocaleString('es-CO', {
    minimumFractionDigits: 0,
    maximumFractionDigits: valor > 999 ? 0 : 1,
  })}${suffix ? ' ' + suffix : ''}`;

  return (
    <div className="w-full h-full flex flex-col justify-center p-4">
      <p className="text-sm font-medium text-gray-500 mb-1 truncate">{etiqueta} ({period})</p>
      <div className="flex items-baseline gap-3">
        <h3 className="text-3xl font-bold text-gray-900">{formattedValue}</h3>
        {tendencia !== 0 && (
          <div className={`flex items-center text-sm font-semibold px-2 py-0.5 rounded-full ${
            isPositive ? 'text-green-700 bg-green-100' : 'text-red-700 bg-red-100'
          }`}>
            {isPositive ? <TrendingUp className="w-3.5 h-3.5 mr-1" /> : <TrendingDown className="w-3.5 h-3.5 mr-1" />}
            {Math.abs(tendencia)}%
          </div>
        )}
      </div>
    </div>
  );
};

export default KpiVentasHoy;
